    const updateUsageLocally = (assetId, interaction) => {
      setUsageRows((prev) => {
        const targetId = String(assetId || "").trim();
        if (!targetId)
          return prev;
        const existingIndex = prev.findIndex((row) => String(row.assetId || row.asset_id || "") === targetId);
        if (existingIndex >= 0) {
          const next = [...prev];
          const current = next[existingIndex];
          next[existingIndex] = {
            ...current,
            assetId: targetId,
            useCount: (Number(current.useCount ?? current.use_count ?? 0) || 0) + 1,
            lastUsedAt: new Date().toISOString(),
            lastInteraction: interaction
          };
          return next;
        }
        return [...prev, { assetId: targetId, useCount: 1, lastUsedAt: new Date().toISOString(), lastInteraction: interaction }];
      });
    };
    const persistUsage = async (assetId, interaction = "study") => {
      const clientId = String(session?.clientId || "").trim();
      const teacherId = String(session?.teacherId || "").trim();
      const targetAssetId = String(assetId || "").trim();
      if (!clientId || !teacherId || !targetAssetId)
        return;
      updateUsageLocally(targetAssetId, interaction);
      try {
        await supabase.rpc("record_cardlab_asset_usage", {
          p_client_id: clientId,
          p_teacher_id: teacherId,
          p_asset_id: targetAssetId,
          p_interaction: interaction
        });
      } catch (error) {
        console.warn("[CardLabSessionMode] usage record failed:", error);
      }
    };
